ms varchar(2000) = (select @StoreGrouping as StoreGrouping, @StoreGroup as StoreGroup, @SDate as SDate, @EDate as EDate for json path) 		 		select distinct Item_GUID,Store_GUID,Item_Name,Item_PLU,Item_SKU,Item_Price,Item_POS_Name,Item_Kitchen_Name,Item_Is_Deferred,Item_Is_Discountable,Item_Pricing_Strategy,Sales_Cat_GUID,Sales_Cat,Menu_GUID,Menu_Name,Menu_Group_GUID,Menu_Group_Name,Guest_Count,Item_Tags,Modifier_Group_References,Prep_Stations,Content_Advisories 		into #TempItems 		from toast.dbo.cfg_menu_items_temp  		merge toast.dbo.cfg_menu_items i 		using #TempItems it 		on i.item_guid = it.item_guid 		and i.store_guid = it.store_guid 		and i.menu_guid = it.menu_guid 		and i.Menu_Group_GUID = it.Menu_Group_GUID 		when matched then update set 			i.Item_Name = it.Item_Name, 			i.Item_PLU = it.Item_PLU, 			i.Item_SKU = it.Item_SKU, 			i.Item_Price = it.Item_Price, 			i.Item_POS_Name = it.Item_POS_Name, 			i.Item_Kitchen_Name = it.Item_Kitchen_Name, 			i.Item_Is_Deferred = it.Item_Is_Deferred, 			i.Item_Is_Discountable = it.Item_Is_Discountable, 			i.Item_Pricing_Strategy = it.Item_Pricing_Strategy, 			i.Sales_Cat_GUID = it.Sales_Cat_GUID, 			i.Sales_Cat = it.Sales_Cat, 			i.Menu_GUID = it.Menu_GUID, 			i.Menu_Name = it.Menu_Name, 			i.Menu_Group_GUID = it.Menu_Group_GUID, 			i.Menu_Group_Name = it.Menu_Group_Name, 			i.Guest_Count = it.Guest_Count, 			i.Item_Tags = it.Item_Tags, 			i.Modifier_Group_References = it.Modifier_Group_References, 			i.Prep_Stations = it.Prep_Stations, 			i.Content_Advisories = it.Content_Advisories 		when not matched by target then 			insert (Item_GUID,Store_GUID,Item_Name,Item_PLU,Item_SKU,Item_Price,Item_POS_Name,Item_Kitchen_Name,Item_Is_Deferred,Item_Is_Discountable,Item_Pricing_Strategy,Sales_Cat_GUID,Sales_Cat,Menu_GUID,Menu_Name,Menu_Group_GUID,Menu_Group_Name,Guest_Count,Item_Tags,Modifier_Group_References,Prep_Stations,Content_Advisories) 			values (it.Item_GUID, it.Store_GUID, it.Item_Name, it.Item_PLU, it.Item_SKU, it.Item_Price, it.Item_POS_Name, it.Item_Kitchen_Name, it.Item_Is_Deferred, it.Item_Is_Discountable, it.Item_Pricing_Strategy, it.Sales_Cat_GUID, it.Sales_Cat, it.Menu_GUID, it.Menu_Name, it.Menu_Group_GUID, it.Menu_Group_Name, it.Guest_Count, it.Item_Tags, it.Modifier_Group_References, it.Prep_Stations, it.Content_Advisories);  		drop table #TempItems  		truncate table toast.dbo.cfg_menu_items_temp                  -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName; 			--,@Params = @Params;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine; 			--,@Params = @Params;         THROW;     END CATCH END